        "819": { n: "კედლების სიბრტყისა და კუთხეების გადახრა ვერტიკალიდან", t: "SP 70.13330.2012 (ცხრ. 9.8); ტექ. რუკა\nდაშვება არაუმეტეს 10 მმ სართულის მთელ სიმაღლეზე" },
        "820": { n: "წყობის ვერტიკალური ზედაპირის უსწორმასწორობები.", t: "SP 70.13330.2012 (ცხრ. 9.8); ტექ. რუკა\nდაშვება არაუმეტეს 5 მმ სართულის მთელ სიმაღლეზე" },
        "821": { n: "СКЦ წყობა დაბინძურების, ნაზეთარისა და ჩაღრმავებების გარეშე.", t: "SP 70.13330.2012; ტექ. რუკა" },
