        "1421": { n: "მინის ტიპი", t: "ტდ. სწგ. ნაწრთობი (6–8 მმ) ან ტრიპლექსი" },
        "1422": { n: "ჩარჩოში ფიქსაცია", t: "ტდ. სწგ. მექანიკური მომჭერები" },
