        "1425": { n: "შიდა ჰერმეტიზაცია", t: "ტდ. სწგ. ბუტილის ლენტი" },
        "1426": { n: "ნაკერების თბოიზოლაცია", t: "ტდ. სწგ. არ მოითხოვება" },
        "1427": { n: "ვერტიკალიდან გადახრა", t: "ტდ. სწგ. ≤2 მმ/1 მ" },
