        "1429": { n: "სადრენაჟო ხვრელები", t: "ტდ. სწგ. Ø5 მმ, ბიჯი ≤500 მმ" },
        "1413": { n: "პროფილის მასალა", t: "ტდ. სწგ. პროექტის მიხედვით, ალუმინი თერმოგაწყვეტით" },
        "1414": { n: "კედელზე მიმაგრება", t: "ტდ. სწგ. უჟანგავი ფოლადის ანკერები (Ø არანაკლებ 8 მმ)" },
