        "3110": { n: "კარის ფრთაზე მისადები ძალვა დამჭიდროებელი სამარაგოების საჭირო შეკუმშვამდე დახურვისას არ უნდა აღემატებოდეს 120 ნ-ს, ამასთან დახურულ მდგომარეობაში საკეტის ჩამკეტი და ურდული უნდა მუშაობდეს გაჭედვის გარეშე", t: "GOST 31173—2016 პ.5.3.9\nკონტროლის მეთოდი: ინსტრუმენტული" },
        "3111": { n: "კარის ფრთის გასაღებად საჭირო ძალვა არ უნდა აღემატებოდეს 75 ნ-ს (ერგონომიკული მოთხოვნები)", t: "GOST 31173—2016 პ.5.3.9\nკონტროლის მეთოდი: ინსტრუმენტული" },
        "3112": { n: "გატეხვაგამძლე შესრულებით დამზადებული კარის ბლოკების შესაბამისობა GOST R 51242—98-ის მოთხოვნებთან", t: "GOST R 51242—98\nკონტროლის მეთოდი: გამოცდის დასკვნა" },
        "3113": { n: "მეტალის საბინაო შესასვლელი კარისა და კარის ჩარჩოს გარეგნული სახე: შეესაბამება ეტალონ-ნიმუშს", t: "GOST 31173—2016 პ.5.3.11\nკონტროლის მეთოდი: მეტალის საბინაო შესასვლელი კარის ეტალონის ხელმოწერილი აქტი" },
        "3114": { n: "ფერის, ბზინვარებისა და ზედაპირის დეფექტების განსხვავებები, რომლებიც ჩანს შეუიარაღებელი თვალით 0,6—0,8 მ მანძილიდან ბუნებრივი განათებისას არანაკლებ 300 ლქ, დაუშვებელია", t: "GOST 31173—2016 პ.5.3.11\nკონტროლის მეთოდი: ინსტრუმენტული" },
        "3115": { n: "შიდა კარის ბლოკებისთვის გამოიყენება კოროზიისგან დაცული ფოლადი, რომელიც უზრუნველყოფს კოროზიისადმი მედეგობას მარილის ნისლში არანაკლებ 150 სთ გამოცდისას", t: "GOST 31173—2016 პ.5.4.2\nკონტროლის მეთოდი: გამოცდის დასკვნა" },
        "3116": { n: "კარის ბლოკებზე ყველა შედულების ნაკერი უნდა იყოს გლუვი, ნაწილაკების გარეშე, გაპრიალებული", t: "GOST 31173—2016 პ.5.3.12\nკონტროლის მეთოდი: ვიზუალური და ინსტრუმენტული" },
        "3117": { n: "ჩარჩოს შიდა ნაკერები უნდა იყოს მთლიანად გადადუღებული. შედულების შეერთებების კატეგორიებისა და დონის მახასიათებლები — GOST 23118-ის მიხედვით", t: "GOST 23118\nკონტროლის მეთოდი: ვიზუალური და ინსტრუმენტული" },
        "3118": { n: "კარის ბლოკის საღებავ-ლაქის საფარის სისქე", t: "კონტროლის მეთოდი: ინსტრუმენტული" },
        "3119": { n: "საღებავ-ლაქის საფარის შეჭიდულობის (ადჰეზიის) სიმტკიცე არანაკლებ მე-2 ბალისა", t: "GOST 31149\nკონტროლის მეთოდი: დოკუმენტური" },
        "3120": { n: "თითოეული კარის ბლოკის მარკირება ეტიკეტით", t: "მითითებით: მწარმოებელი საწარმოს დასახელება, ტიპი, ნაწარმის პირობითი აღნიშვნა სიმტკიცის კლასის მითითებით, დამზადების თარიღი და/ან შეკვეთის ნომერი, ნიშანი (შტამპი), რომელიც ადასტურებს ნაწარმის მიღებას ტექნიკური კონტროლის სამსახურის მიერ. ნაწარმის მარკირება უნდა ასახავდეს შეკვეთაში მითითებულ კარების ტიპის ფაქტობრივ მოთხოვნებს, აგრეთვე მწარმოებლის მიერ მითითებულ იდენტიფიკაციის ჩატარების შესაძლებლობას დამზადების ნამდვილობის დასადგენად.\nGOST 31173—2016 პ.5.7.4\nკონტროლის მეთოდი: ვიზუალურად, დოკუმენტურად" },
        "3121": { n: "კარის ბლოკების ხარისხის დადასტურება", t: "მასალებისა და კომპლექტაციის დეტალების შემომავალი კონტროლი; ოპერაციული საწარმოო კონტროლი; მზა ნაწარმის ცვლაში ერთხელ მისაღები კონტროლი; ნაწარმის ყოველი პარტიის საკონტროლო მიღება-ჩაბარების გამოცდები მწარმოებელი საწარმოს ტექნიკური კონტროლის სამსახურის მიერ; ნაწარმის პერიოდული და სერტიფიკაციული გამოცდები დამოუკიდებელ საგამოცდო ცენტრებში; საკვალიფიკაციო გამოცდები.\nGOST 31173—2016\nკონტროლის მეთოდი: დოკუმენტური" },
        "3122": { n: "კარის მარკირების არსებობა", t: "GOST 31173—2016 პ.5.7\nკონტროლის მეთოდი: ვიზუალურად, დოკუმენტურად" },
        "3123": { n: "ნაწარმის პასპორტი დანართი D-ს მიხედვით", t: "GOST 31173—2016 პ.6.13.1\nკონტროლის მეთოდი: დოკუმენტური" },
