        "4084": { n: "სადრენაჟო ხვრელები", t: "ტდ. სწგ. Ø5 მმ, ბიჯი ≤500 მმ" },
        "4085": { n: "მინის ტიპი", t: "ტდ. სწგ. ნაწრთობი (6–8 მმ) ან ტრიპლექსი" },
