        "4088": { n: "კედელზე მიმაგრება", t: "ტდ. სწგ. უჟანგავი ფოლადის ანკერები (Ø არანაკლებ 8 მმ)" },
        "4089": { n: "მიმაგრების ბიჯი", t: "ტდ. სწგ. ≤800 მმ" },
        "4090": { n: "ღრეჩოები სითბური გაფართოებისთვის", t: "ტდ. სწგ. 8–12 მმ" },
