        "4259": { n: "წინასწარი რეგულირება", t: "GOST 34378-2018 ცხრ. L1 შეამოწმეთ ფრთების მუშაობა (გაღება/დახურვა ძალისხმევის გარეშე)" },
        "4260": { n: "ფანჯრის ბლოკის განლაგება", t: "საპროექტო და სამუშაო დოკუმენტაციასთან შესაბამისობა" },
        "4261": { n: "ჩარჩოს გადახრა", t: "GOST 34378-2018 დანართი Zh (კონტროლის რუკა). არაუმეტეს 1,5 მმ 1 მ-ზე, მაგრამ არაუმეტეს 3 მმ მთელ სიგრძეზე" },
        "4262": { n: "ნაკეთობების მთლიანობა", t: "GOST 21519-2022 ცხრ.1 თვალსაჩინო დეფექტების არარსებობა (ბზარები, ნაჭდევები, გაცვეთა)" },
        "4263": { n: "წინასწარი რეგულირება", t: "GOST 21519-2022 პ. 8.3. შეამოწმეთ ფრთების მუშაობა (გაღება/დახურვა ძალისხმევის გარეშე)" },
        "4264": { n: "პროფილის მასალა", t: "პროექტის მიხედვით, ტდ. სწგ. ალუმინი თერმოგაწყვეტის გარეშე" },
        "4265": { n: "ღრეჩოები სითბური გაფართოებისთვის", t: "ტდ. სწგ. 5–10 მმ" },
        "4266": { n: "სადრენაჟო ხვრელები", t: "ტდ. სწგ. Ø5 მმ, ბიჯი ≤500 მმ" },
        "4267": { n: "მინის ტიპი", t: "ტდ. სწგ. ნაწრთობი (6–8 მმ) ან ტრიპლექსი" },
        "4268": { n: "ნაკეთობების მთლიანობა", t: "GOST 34378-2018 ცხრ. L1. თვალსაჩინო დეფექტების არარსებობა (ბზარები, ნატეხები, პროფილის გახეხილობა)" },
        "4269": { n: "რეგულირება", t: "GOST 34378-2018 ცხრ. L1 შეამოწმეთ ფრთების მუშაობა (გაღება/დახურვა ძალისხმევის გარეშე)" },
